/* Shared page chrome — background scenes, theme, parallax.
 *
 * Every page used to hand-copy the same ~15 lines of .topo-bg markup. That
 * markup now lives here and is built from <body data-scene="...">, so there is
 * one place to change the background art.
 *
 * Scenes: alpine (default) | depth | snow | plot
 * Pages can switch at runtime — Field Notes cross-fades the whole page
 * background when you move between Backcountry / Dive / Ski.
 *
 * Ridge silhouettes are generated by fractal midpoint displacement from a
 * fixed seed rather than hand-written polylines: same shape on every load,
 * but with the irregularity real skylines have.
 */
(function () {
  "use strict";

  var REDUCED = window.matchMedia &&
    window.matchMedia("(prefers-reduced-motion: reduce)").matches;

  /* ------------------------------ seeded noise ------------------------------ */

  function rng(seed) {
    var s = seed >>> 0;
    return function () {
      s ^= s << 13; s >>>= 0;
      s ^= s >> 17;
      s ^= s << 5;  s >>>= 0;
      return s / 4294967296;
    };
  }

  /* Midpoint displacement: subdivide a segment, nudging each new midpoint by a
     random amount that halves with each level. Low roughness = smooth
     rolling hills, high = jagged alpine. */
  function ridgeProfile(seed, opts) {
    var rand = rng(seed);
    var depth = opts.depth || 6;
    var rough = opts.rough == null ? 0.62 : opts.rough;
    var pts = [
      { x: 0, y: opts.left },
      { x: 1, y: opts.right }
    ];
    var amp = opts.amp;

    for (var d = 0; d < depth; d++) {
      var next = [pts[0]];
      for (var i = 1; i < pts.length; i++) {
        var a = pts[i - 1], b = pts[i];
        next.push({
          x: (a.x + b.x) / 2,
          y: (a.y + b.y) / 2 + (rand() * 2 - 1) * amp
        });
        next.push(b);
      }
      pts = next;
      amp *= rough;
    }
    return pts;
  }

  /* Catmull-Rom through the points, emitted as cubic beziers. Straight polyline
     segments are what made the old ridges read as clip-art; curvature through
     the saddles is most of the difference. `tension` near 0 keeps peaks sharp. */
  function smoothPath(pts, w, h, tension) {
    var t = tension == null ? 0.22 : tension;
    var X = function (p) { return (p.x * w).toFixed(1); };
    var Y = function (p) { return (p.y * h).toFixed(1); };
    var d = "M" + X(pts[0]) + "," + Y(pts[0]);

    for (var i = 0; i < pts.length - 1; i++) {
      var p0 = pts[i - 1] || pts[i];
      var p1 = pts[i];
      var p2 = pts[i + 1];
      var p3 = pts[i + 2] || p2;
      var c1 = { x: p1.x + (p2.x - p0.x) * t, y: p1.y + (p2.y - p0.y) * t };
      var c2 = { x: p2.x - (p3.x - p1.x) * t, y: p2.y - (p3.y - p1.y) * t };
      d += "C" + X(c1) + "," + Y(c1) + " " + X(c2) + "," + Y(c2) +
           " " + X(p2) + "," + Y(p2);
    }
    return d;
  }

  function ridgeSvg(cls, seed, cfg) {
    var W = 1440, H = 420;
    var pts = ridgeProfile(seed, cfg);
    var d = smoothPath(pts, W, H, cfg.tension) +
            " L" + W + "," + H + " L0," + H + " Z";
    return '<svg class="ridge-layer ' + cls + '" viewBox="0 0 ' + W + ' ' + H +
           '" preserveAspectRatio="none" aria-hidden="true">' +
           '<path d="' + d + '"/></svg>';
  }

  /* A treeline on the nearest ridge: irregular conifer spikes riding the same
     profile the ridge uses, so they sit on the skyline instead of floating. */
  function treeline(seed, cfg) {
    var W = 1440, H = 420;
    var pts = ridgeProfile(seed, cfg);
    var rand = rng(seed ^ 0x9e37);
    var d = "";
    var step = 7;

    for (var i = 2; i < pts.length - 2; i += step) {
      var p = pts[i];
      var x = p.x * W;
      var y = p.y * H;
      var hgt = 7 + rand() * 13;
      var wid = 2 + rand() * 2.6;
      // a lopsided spruce: two sides, slightly different, never mirrored
      d += "M" + (x - wid).toFixed(1) + "," + (y + 2).toFixed(1) +
           "L" + x.toFixed(1) + "," + (y - hgt).toFixed(1) +
           "L" + (x + wid * (0.7 + rand() * 0.6)).toFixed(1) + "," + (y + 2).toFixed(1) + "Z";
      step = 5 + Math.floor(rand() * 5);
    }
    return '<svg class="treeline" viewBox="0 0 ' + W + ' ' + H +
           '" preserveAspectRatio="none" aria-hidden="true"><path d="' + d + '"/></svg>';
  }

  function stars(seed, count) {
    var rand = rng(seed);
    var out = "";
    for (var i = 0; i < count; i++) {
      var x = rand() * 100;
      var y = rand() * 62;              // keep them above the ridgeline
      var r = 0.6 + rand() * 1.1;
      var o = 0.25 + rand() * 0.6;
      var delay = (rand() * 9).toFixed(2);
      out += '<span class="star" style="left:' + x.toFixed(2) + '%;top:' + y.toFixed(2) +
             '%;width:' + r.toFixed(2) + 'px;height:' + r.toFixed(2) +
             'px;--star-o:' + o.toFixed(2) + ';animation-delay:' + delay + 's"></span>';
    }
    return out;
  }

  function repeat(n, fn) {
    var out = "";
    for (var i = 0; i < n; i++) out += fn(i);
    return out;
  }

  /* -------------------------------- scenes -------------------------------- */

  var SCENES = {
    alpine: function () {
      return '' +
        '<div class="sky-stars">' + stars(0xa1b1e, 90) + '</div>' +
        '<div class="celestial"></div>' +
        '<div class="glow"></div>' +
        '<div class="ridges">' +
          ridgeSvg("ridge-layer--1", 0x51d3, { left: 0.40, right: 0.30, amp: 0.17, depth: 6, rough: 0.52, tension: 0.07 }) +
          ridgeSvg("ridge-layer--2", 0x2b7f, { left: 0.56, right: 0.48, amp: 0.15, depth: 6, rough: 0.54, tension: 0.08 }) +
          ridgeSvg("ridge-layer--3", 0x77c4, { left: 0.70, right: 0.63, amp: 0.13, depth: 6, rough: 0.58, tension: 0.1 }) +
          ridgeSvg("ridge-layer--4", 0x3e91, { left: 0.84, right: 0.80, amp: 0.07, depth: 5, rough: 0.64, tension: 0.16 }) +
          treeline(0x3e91, { left: 0.84, right: 0.80, amp: 0.07, depth: 5, rough: 0.64 }) +
        '</div>' +
        '<div class="mist mist--a"></div>' +
        '<div class="mist mist--b"></div>' +
        '<div class="mist mist--c"></div>';
    },

    /* Underwater: a spring cavern. Light comes from the surface above in
       shafts, particulate drifts through it, and the walls close in at the
       edges — the Florida karst look rather than open blue water. */
    depth: function () {
      var rand = rng(0xd33d);
      return '' +
        '<div class="caustics"></div>' +
        '<div class="shafts">' + repeat(5, function (i) {
          return '<span class="shaft" style="left:' + (6 + i * 21) + '%;--shaft-w:' +
                 (7 + rand() * 9).toFixed(1) + 'vw;--shaft-r:' + (-14 + rand() * 28).toFixed(1) +
                 'deg;animation-delay:-' + (rand() * 14).toFixed(1) + 's"></span>';
        }) + '</div>' +
        '<div class="motes">' + repeat(34, function () {
          var s = (1.4 + rand() * 3).toFixed(1);
          return '<span class="mote" style="left:' + (rand() * 100).toFixed(2) +
                 '%;bottom:-' + (rand() * 30).toFixed(0) + '%;width:' + s + 'px;height:' + s +
                 'px;animation-duration:' + (16 + rand() * 26).toFixed(1) +
                 's;animation-delay:-' + (rand() * 30).toFixed(1) + 's"></span>';
        }) + '</div>' +
        '<div class="cavern-walls"></div>';
    },

    /* Snow: the same ridges under a colder palette, with the sun low and
       flat light, plus falling snow. */
    snow: function () {
      var rand = rng(0x5701);
      return '' +
        '<div class="glow glow--cold"></div>' +
        '<div class="ridges ridges--snow">' +
          ridgeSvg("ridge-layer--1", 0x8c21, { left: 0.38, right: 0.28, amp: 0.18, depth: 6, rough: 0.5, tension: 0.06 }) +
          ridgeSvg("ridge-layer--2", 0x44a8, { left: 0.58, right: 0.49, amp: 0.15, depth: 6, rough: 0.54, tension: 0.08 }) +
          ridgeSvg("ridge-layer--3", 0x1f60, { left: 0.78, right: 0.72, amp: 0.10, depth: 6, rough: 0.6, tension: 0.14 }) +
          treeline(0x1f60, { left: 0.78, right: 0.72, amp: 0.10, depth: 6, rough: 0.6 }) +
        '</div>' +
        '<div class="snowfall">' + repeat(46, function () {
          var s = (2 + rand() * 3.4).toFixed(1);
          return '<span class="flake" style="left:' + (rand() * 100).toFixed(2) +
                 '%;width:' + s + 'px;height:' + s + 'px;--drift:' +
                 (-30 + rand() * 60).toFixed(0) + 'px;animation-duration:' +
                 (11 + rand() * 17).toFixed(1) + 's;animation-delay:-' +
                 (rand() * 26).toFixed(1) + 's"></span>';
        }) + '</div>' +
        '<div class="mist mist--a"></div>' +
        '<div class="mist mist--c"></div>';
    },

    /* Plotted: the ridge redrawn as a chart on a faint grid — the same line,
       read as a price series instead of a skyline. */
    plot: function () {
      var pts = ridgeProfile(0x9a77, { left: 0.74, right: 0.36, amp: 0.15, depth: 6, rough: 0.66 });
      var line = smoothPath(pts, 1440, 420, 0.2);
      return '' +
        '<div class="plot-grid"></div>' +
        '<div class="glow glow--cool"></div>' +
        '<div class="ridges ridges--plot">' +
          '<svg class="ridge-layer ridge-layer--2" viewBox="0 0 1440 420" preserveAspectRatio="none" aria-hidden="true">' +
            '<path d="' + line + ' L1440,420 L0,420 Z"/></svg>' +
          '<svg class="plot-line" viewBox="0 0 1440 420" preserveAspectRatio="none" aria-hidden="true">' +
            '<path d="' + line + '"/></svg>' +
        '</div>' +
        '<div class="mist mist--b"></div>';
    }
  };

  /* ------------------------------ scene mount ------------------------------ */

  var bg, current = null, built = {};

  function mountScene(name) {
    if (!SCENES[name]) name = "alpine";
    if (name === current) return;

    if (!built[name]) {
      var el = document.createElement("div");
      el.className = "scene scene--" + name;
      el.setAttribute("data-scene-layer", name);
      el.innerHTML = SCENES[name]();
      bg.appendChild(el);
      built[name] = el;
      // force a frame so the fade-in transition actually runs
      void el.offsetWidth;
    }

    Object.keys(built).forEach(function (k) {
      built[k].classList.toggle("is-active", k === name);
    });
    bg.setAttribute("data-scene", name);
    document.documentElement.setAttribute("data-scene", name);
    current = name;
  }

  function buildBackground() {
    bg = document.querySelector(".topo-bg");
    if (!bg) {
      bg = document.createElement("div");
      bg.className = "topo-bg";
      document.body.insertBefore(bg, document.body.firstChild);
    }
    bg.setAttribute("aria-hidden", "true");
    bg.innerHTML = "";
    mountScene(document.body.getAttribute("data-scene") || "alpine");
  }

  /* -------------------------------- the sky -------------------------------- */
  /* sky.js decides the phase and owns the attributes; chrome.js only has to
     put the disc where the body actually is and wire the toggle. */

  /* Azimuth to screen: the view faces south, so due east sits at the left edge
     and due west at the right. Anything round the north side (which happens at
     night in summer) clamps to the nearer edge rather than wrapping. */
  function skyPosition(body) {
    var left = (body.az - 90) / 180 * 100;
    left = Math.max(-6, Math.min(106, left));
    // altitude 0 is the horizon, which sits about 58% down the viewport
    var HORIZON = 58, TOP = 5;
    var top = HORIZON - (Math.max(0, body.alt) / 90) * (HORIZON - TOP);
    return { left: left, top: top, up: body.alt > -2 };
  }

  function paintCelestial() {
    var el = document.querySelector(".celestial");
    if (!el || !window.Sky || !window.Sky.state) return;
    var st = window.Sky.state;

    // Pinned modes have no real sun to point at, so park it somewhere sensible.
    if (window.Sky.mode !== "auto") {
      el.style.left = "74%";
      el.style.top = window.Sky.mode === "night" ? "18%" : "26%";
      el.classList.toggle("is-moon", window.Sky.mode === "night");
      el.style.removeProperty("--moon-shift");
      return;
    }

    var body = st.dark ? st.moon : st.sun;
    var pos = skyPosition(body);
    el.style.left = pos.left.toFixed(2) + "%";
    el.style.top = pos.top.toFixed(2) + "%";
    el.classList.toggle("is-moon", !!st.dark);
    // below the horizon it would be underground; fade it rather than jump it
    el.style.opacity = pos.up ? "1" : "0";

    if (st.dark) {
      // terminator offset: full moon 0, new moon a full diameter across
      var shift = (1 - 2 * st.moon.illum) * (st.moon.waxing ? -1 : 1);
      el.style.setProperty("--moon-shift", (shift * 100).toFixed(1) + "%");
    } else {
      el.style.removeProperty("--moon-shift");
    }
  }

  function describeSky() {
    if (!window.Sky || !window.Sky.state) return "Sky";
    var st = window.Sky.state;
    var names = {
      night: "Night", dawn: "Dawn", "first-light": "First light",
      sunrise: "Sunrise", morning: "Morning", midday: "Midday",
      afternoon: "Afternoon", sunset: "Sunset", twilight: "Twilight",
      nightfall: "Nightfall"
    };
    if (window.Sky.mode === "day") return "Sky: pinned to midday";
    if (window.Sky.mode === "night") return "Sky: pinned to night";
    return names[st.phase] + " over St. Petersburg" +
           (st.localTime ? ", " + st.localTime + " ET" : "");
  }

  function labelToggle() {
    var btn = document.querySelector(".theme-toggle");
    if (!btn || !window.Sky) return;
    btn.setAttribute("data-mode", window.Sky.mode);
    var label = describeSky();
    btn.setAttribute("title", label + " — click to change");
    btn.setAttribute("aria-label", label + ". Click to change the sky.");
  }

  function buildThemeToggle() {
    if (document.querySelector(".theme-toggle")) return;
    var btn = document.createElement("button");
    btn.type = "button";
    btn.className = "theme-toggle";
    btn.innerHTML =
      '<svg viewBox="0 0 24 24" aria-hidden="true">' +
        '<circle class="t-sun" cx="12" cy="12" r="4.4"/>' +
        '<g class="t-rays"><path d="M12 1.6v2.6M12 19.8v2.6M22.4 12h-2.6M4.2 12H1.6' +
        'M19.4 4.6l-1.9 1.9M6.5 17.5l-1.9 1.9M19.4 19.4l-1.9-1.9M6.5 6.5L4.6 4.6"/></g>' +
        '<path class="t-moon" d="M20 14.2A8.4 8.4 0 0 1 9.8 4a8.4 8.4 0 1 0 10.2 10.2z"/>' +
      '</svg>';
    btn.addEventListener("click", function () {
      if (window.Sky) window.Sky.cycle();
    });
    document.body.appendChild(btn);
  }

  /* ------------------------------- parallax ------------------------------- */
  /* Two inputs, both written as CSS custom properties on <body> and consumed by
     the ridge transforms: pointer position (fine pointers only) and scroll
     depth. Scroll is what gives the ridges their sense of standing still while
     the page moves over them. */

  function initParallax() {
    if (REDUCED) return;

    var fine = window.matchMedia && window.matchMedia("(pointer: fine)").matches;
    var raf = null;
    var px = 0, py = 0, sy = 0;

    function write() {
      raf = null;
      document.body.style.setProperty("--parallax-x", px.toFixed(3));
      document.body.style.setProperty("--parallax-y", py.toFixed(3));
      document.body.style.setProperty("--scroll-y", sy.toFixed(4));
    }
    function schedule() {
      if (raf === null) raf = requestAnimationFrame(write);
    }

    if (fine) {
      window.addEventListener("mousemove", function (e) {
        px = (e.clientX / window.innerWidth - 0.5) * 2;
        py = (e.clientY / window.innerHeight - 0.5) * 2;
        schedule();
      }, { passive: true });
    }

    window.addEventListener("scroll", function () {
      var max = document.documentElement.scrollHeight - window.innerHeight;
      sy = max > 0 ? Math.min(1, window.scrollY / max) : 0;
      schedule();
    }, { passive: true });

    write();
  }

  /* --------------------------------- boot --------------------------------- */

  function boot() {
    buildBackground();
    buildThemeToggle();
    paintCelestial();
    labelToggle();
    initParallax();

    // sky.js re-runs every minute and on every toggle; follow it
    if (window.Sky) {
      window.Sky.onchange = function () { paintCelestial(); labelToggle(); };
    }
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", boot);
  } else {
    boot();
  }

  window.Chrome = {
    setScene: mountScene,
    ridgeProfile: ridgeProfile,
    smoothPath: smoothPath,
    reducedMotion: REDUCED
  };
})();
